-- Generated by scripts/setup_bigquery.py --print-ddl. Replace {project}.{dataset} with `project.dataset`.

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.launches` (
  launch_id STRING NOT NULL,
  launch_name STRING NOT NULL,
  product_name STRING,
  cost_center STRING OPTIONS(description="Finance cost center that carries the spend"),
  embargo_date DATE NOT NULL OPTIONS(description="Public press embargo lifts"),
  in_hand_by DATE NOT NULL OPTIONS(description="Everything must be in the recipients' hands by this date"),
  owner STRING
) OPTIONS(description="Product launches to equip, with the two dates that matter: in-hand deadline and press embargo.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.assets` (
  sku STRING NOT NULL,
  name STRING NOT NULL,
  component_type STRING NOT NULL OPTIONS(description="BOX, APPAREL, POWER, PERSONALISATION, DISPLAY, FOLDER, PRINT"),
  ship_factor FLOAT64 NOT NULL OPTIONS(description="Relative size/weight: multiplies the shipping lane cost"),
  suggested_per_person FLOAT64 OPTIONS(description="Units we suggest per campaign guest (blank: not by headcount)")
) OPTIONS(description="Launch collateral catalog (one row per sellable item).");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.bundle_templates` (
  bundle_type STRING NOT NULL OPTIONS(description="GUEST_KIT, VENUE_DISPLAY, SALES_PACK"),
  description STRING,
  sku_pattern STRING NOT NULL OPTIONS(description="A SKU, or a pattern with {size} / {plug}"),
  qty_per_bundle INT64 NOT NULL,
  split_by STRING NOT NULL OPTIONS(description="NONE, SIZE or PLUG: how the SKU is chosen per recipient"),
  suggested_per_person FLOAT64 OPTIONS(description="Bundles we suggest per campaign guest (blank: not by headcount)")
) OPTIONS(description="What goes into one bundle (guest welcome kit, venue display stand, sales folder).");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.guests` (
  guest_id STRING NOT NULL,
  launch_id STRING NOT NULL,
  handle STRING NOT NULL,
  name STRING,
  size STRING NOT NULL OPTIONS(description="S, M, L, XL"),
  region STRING NOT NULL OPTIONS(description="US, EMEA, APAC"),
  plug_type STRING NOT NULL OPTIONS(description="US-A, UK-G, EU-C, JP-A, AU-I")
) OPTIONS(description="VIP guest list: size and power-plug per recipient (personalisation).");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.regional_split` (
  bundle_type STRING NOT NULL,
  region STRING NOT NULL,
  share_pct FLOAT64 NOT NULL
) OPTIONS(description="How a non-personalised bundle is spread over regions (share in percent).");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.depots` (
  depot_id STRING NOT NULL,
  depot_name STRING NOT NULL,
  region STRING NOT NULL
) OPTIONS(description="Regional marketing depots holding reusable surplus stock.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.depot_stock` (
  depot_id STRING NOT NULL,
  sku STRING NOT NULL,
  on_hand INT64 NOT NULL
) OPTIONS(description="Surplus units physically on hand per depot and SKU.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.transit_lanes` (
  from_region STRING NOT NULL,
  to_region STRING NOT NULL,
  days INT64 NOT NULL OPTIONS(description="Transit days"),
  cost_per_unit FLOAT64 NOT NULL OPTIONS(description="USD per ship_factor unit")
) OPTIONS(description="Shipping time and cost between regions.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.vendors` (
  vendor_id STRING NOT NULL,
  vendor_name STRING NOT NULL,
  home_region STRING NOT NULL OPTIONS(description="Where it ships from"),
  active BOOL NOT NULL OPTIONS(description="Only active vendors are planned")
) OPTIONS(description="Approved manufacturers.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.venues` (
  venue_id STRING NOT NULL,
  venue_name STRING NOT NULL OPTIONS(description="What the user says: USA, Canada, London, Singapore"),
  country STRING,
  region STRING NOT NULL OPTIONS(description="US, EMEA or APAC: the region that serves it"),
  served_from STRING OPTIONS(description="Plain words: where the goods come from")
) OPTIONS(description="Where a campaign can be held, and the region that serves it (vendors, warehouse, shipping lanes).");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.vendor_date_pricing` (
  vendor_id STRING NOT NULL OPTIONS(description="A vendor id, or * for every vendor that has no rows of its own"),
  min_days_ahead INT64 NOT NULL OPTIONS(description="Applies when the in-hand date is at least this many days away"),
  price_factor FLOAT64 NOT NULL OPTIONS(description="Multiplies the unit price: 0.95 = 5% off, 1.10 = 10% rush charge"),
  label STRING OPTIONS(description="Plain words for the user")
) OPTIONS(description="Vendor price by how many days ahead the order is placed: early-bird discounts and rush charges.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.vendor_offers` (
  vendor_id STRING NOT NULL,
  sku STRING NOT NULL,
  variant STRING NOT NULL OPTIONS(description="STANDARD or ECO"),
  unit_price FLOAT64 NOT NULL OPTIONS(description="USD per unit"),
  lead_days INT64 NOT NULL OPTIONS(description="Production lead time"),
  carbon_kg FLOAT64 NOT NULL OPTIONS(description="kg CO2e per unit")
) OPTIONS(description="Vendor price, production lead time and carbon per SKU and variant.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.planning_rules` (
  rule_key STRING NOT NULL OPTIONS(description="MIN_BUFFER_HOURS, TARGET_BUFFER_HOURS, DEPOT_HANDLING_DAYS, ..."),
  rule_value FLOAT64 NOT NULL,
  description STRING
) OPTIONS(description="Numbers that steer the planner (safety buffers, handling time), editable by the launch team.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.approval_policy` (
  tier STRING NOT NULL OPTIONS(description="AUTOPILOT, VP_SIGNOFF, CMO_SIGNOFF"),
  min_amount FLOAT64 NOT NULL OPTIONS(description="Exclusive lower bound"),
  max_amount FLOAT64 NOT NULL OPTIONS(description="Inclusive upper bound"),
  requires_human BOOL NOT NULL,
  approver_role STRING NOT NULL
) OPTIONS(description="Sign-off tiers by amount: who decides, and whether a person must.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.approvers` (
  approver_role STRING NOT NULL,
