  active BOOL NOT NULL
) OPTIONS(description="Email addresses per approver role (configurable). Role 'Launch Team' receives tracking updates.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.launch_requests` (
  request_id STRING NOT NULL,
  launch_id STRING NOT NULL,
  summary STRING,
  created_at TIMESTAMP NOT NULL
) OPTIONS(description="Every brief registered by the root agent.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.requirement_lines` (
  request_id STRING NOT NULL,
  line_no INT64 NOT NULL,
  bundle_type STRING NOT NULL,
  channel STRING NOT NULL OPTIONS(description="GUESTS, VENUES, SALES"),
  sku STRING NOT NULL,
  region STRING NOT NULL OPTIONS(description="Destination region"),
  quantity INT64 NOT NULL,
  created_at TIMESTAMP NOT NULL
) OPTIONS(description="The brief broken down into what is needed where: one line per SKU and destination region.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.scenarios` (
  scenario_id STRING NOT NULL OPTIONS(description="<request_id>-<FN|RB|EC>"),
  request_id STRING NOT NULL,
  option_code STRING NOT NULL OPTIONS(description="FULL_NEW, REBALANCE or ECO"),
  option_name STRING NOT NULL,
  total_cost FLOAT64 NOT NULL OPTIONS(description="USD, product plus shipping"),
  shipping_cost FLOAT64 NOT NULL OPTIONS(description="USD"),
  savings_usd FLOAT64 NOT NULL OPTIONS(description="Versus the full new build"),
  delivery_date DATE NOT NULL OPTIONS(description="When the last line arrives"),
  buffer_hours INT64 NOT NULL OPTIONS(description="Hours between delivery and the in-hand deadline (negative = late)"),
  carbon_kg FLOAT64 NOT NULL,
  risk STRING NOT NULL,
  feasible BOOL NOT NULL OPTIONS(description="Meets the in-hand deadline and every line has a source"),
  recommended BOOL NOT NULL,
  summary STRING OPTIONS(description="One-line description"),
  created_at TIMESTAMP NOT NULL
) OPTIONS(description="The sourcing options computed for a request (full new build, depot rebalance, eco launch).");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.scenario_lines` (
  line_id STRING NOT NULL OPTIONS(description="<scenario_id>-L<nn>"),
  scenario_id STRING NOT NULL,
  request_id STRING NOT NULL,
  channel STRING NOT NULL,
  sku STRING NOT NULL,
  region STRING NOT NULL OPTIONS(description="Destination region"),
  quantity INT64 NOT NULL,
  source_type STRING NOT NULL OPTIONS(description="DEPOT or VENDOR"),
  source_id STRING NOT NULL OPTIONS(description="depot_id or vendor_id"),
  variant STRING OPTIONS(description="STANDARD or ECO (vendor lines)"),
  unit_price FLOAT64 NOT NULL OPTIONS(description="0 for depot stock"),
  shipping_cost FLOAT64 NOT NULL,
  line_total FLOAT64 NOT NULL,
  days_to_deliver INT64 NOT NULL,
  carbon_kg FLOAT64 NOT NULL,
  execution_status STRING NOT NULL OPTIONS(description="PLANNED or EXECUTED")
) OPTIONS(description="What each scenario would do per line: reuse depot stock or buy from a vendor.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.decisions` (
  decision_id STRING NOT NULL,
  request_id STRING NOT NULL,
  scenario_id STRING NOT NULL,
  option_code STRING NOT NULL,
  tier STRING NOT NULL,
  approver_role STRING NOT NULL,
  approver_emails STRING OPTIONS(description="Comma separated"),
  amount FLOAT64 NOT NULL OPTIONS(description="USD authorised: the scenario total"),
  justification STRING,
  status STRING NOT NULL OPTIONS(description="PENDING, APPROVED, REJECTED or FAILED"),
