  decision_note STRING OPTIONS(description="While pending: execution:<Application Integration execution id>")
) OPTIONS(description="The sign-off on one chosen scenario: autopilot or a human decision through Application Integration.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.depot_holds` (
  hold_id STRING NOT NULL,
  request_id STRING NOT NULL,
  scenario_id STRING NOT NULL,
  line_id STRING NOT NULL,
