  quantity INT64 NOT NULL,
  status STRING NOT NULL OPTIONS(description="ACTIVE, CONSUMED or RELEASED"),
  created_at TIMESTAMP NOT NULL
) OPTIONS(description="Surplus stock held for a pending or approved scenario (released on a rejection).");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.vendor_disruptions` (
