  created_at TIMESTAMP NOT NULL
) OPTIONS(description="Purchase orders issued through Application Integration for the approved scenario.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.depot_transfers` (
  transfer_number STRING NOT NULL OPTIONS(description="TR-<request>-<warehouse>: one transfer per warehouse"),
  request_id STRING NOT NULL,
  line_id STRING NOT NULL OPTIONS(description="The plan lines this transfer covers, comma separated"),
  depot_id STRING NOT NULL,
  sku STRING NOT NULL OPTIONS(description="Items and quantities, in words"),
  region STRING NOT NULL OPTIONS(description="Destination region(s), comma separated"),
  quantity INT64 NOT NULL OPTIONS(description="Total units on the transfer"),
  status STRING NOT NULL,
  integration_execution_id STRING,
  created_at TIMESTAMP NOT NULL
) OPTIONS(description="Stock transfer orders from a depot to the destination region.");

CREATE TABLE IF NOT EXISTS `{project}.{dataset}.audit_log` (
  event_id STRING NOT NULL,
  created_at TIMESTAMP NOT NULL,
  request_id STRING,
  actor STRING NOT NULL OPTIONS(description="Agent or human role"),
  action STRING NOT NULL,
  details STRING OPTIONS(description="JSON text")
) OPTIONS(description="Every governed action: who did what, when.");

CREATE OR REPLACE VIEW `{project}.{dataset}.v_depot_available` AS
SELECT d.depot_id, d.depot_name, d.region, s.sku, s.on_hand,
       IFNULL(SUM(IF(h.status IN ('ACTIVE', 'CONSUMED'), h.quantity, 0)), 0) AS held,
       s.on_hand - IFNULL(SUM(IF(h.status IN ('ACTIVE', 'CONSUMED'), h.quantity, 0)), 0) AS free
FROM `{project}.{dataset}.depot_stock` s
JOIN `{project}.{dataset}.depots` d ON d.depot_id = s.depot_id
LEFT JOIN `{project}.{dataset}.depot_holds` h ON h.depot_id = s.depot_id AND h.sku = s.sku
GROUP BY d.depot_id, d.depot_name, d.region, s.sku, s.on_hand
;

CREATE OR REPLACE VIEW `{project}.{dataset}.v_launch_readiness` AS
SELECT r.request_id, l.launch_id, l.launch_name, l.in_hand_by, l.embargo_date,
       dc.option_code AS chosen_option, dc.status AS decision_status, dc.tier, dc.amount AS authorised_amount,
       sc.delivery_date, sc.buffer_hours,
       CASE WHEN dc.request_id IS NULL THEN 'NO_DECISION'
            WHEN dc.status != 'APPROVED' THEN dc.status
            WHEN sc.buffer_hours < 0 THEN 'RED'
            WHEN sc.buffer_hours < 24 THEN 'AMBER'
            ELSE 'GREEN' END AS readiness,
       (SELECT COUNT(*) FROM `{project}.{dataset}.scenario_lines` x
         WHERE x.scenario_id = dc.scenario_id AND x.execution_status = 'EXECUTED') AS lines_executed,
       (SELECT COUNT(*) FROM `{project}.{dataset}.scenario_lines` x WHERE x.scenario_id = dc.scenario_id) AS lines_total
FROM `{project}.{dataset}.launch_requests` r
JOIN `{project}.{dataset}.launches` l ON l.launch_id = r.launch_id
LEFT JOIN (
  SELECT * FROM `{project}.{dataset}.decisions` QUALIFY ROW_NUMBER() OVER (PARTITION BY request_id ORDER BY created_at DESC) = 1
) dc ON dc.request_id = r.request_id
LEFT JOIN `{project}.{dataset}.scenarios` sc ON sc.scenario_id = dc.scenario_id
;

